export const characters: Character[] = [
  ...monstadtChars,
  ...liyueChars,
  ...inazumaChars,
  ...sumeruChars,
  ...fontaineChars,
];

export const characterList = characters.map(({ id, name, title, element, rarity, weaponType, role, themeColor }) => ({
  id, name, title, element, rarity, weaponType, role, themeColor,
}));

export function getCharacterById(id: string): Character | undefined {
  return characters.find(c => c.id === id);
}

